style.css:
/* Google AquaSphere — google.com */

/* swap these colors if you want */
:root {
  --my-sky: #b9ecf5;
  --my-blue: #168eaf;
  --my-aqua: #65d9d2;
  --my-glass: rgba(231, 255, 255, 0.72);
  --my-text: #174e69;
}

/* dreamy aqua background */
body {
  background: linear-gradient(
    145deg,
    #e4fbff 0%,
    #b5eaf3 40%,
    #8bd8e8 75%,
    #d8ffff 100%
  ) fixed !important;
  color: var(--my-text) !important;
  font-family: "Segoe UI", "Trebuchet MS", sans-serif !important;
}

/* glossy search field */
textarea,
input[type="text"],
input[type="search"] {
  background: linear-gradient(
    180deg,
    rgba(255,255,255,.96),
    rgba(220,250,255,.78)
  ) !important;
  border: 1px solid rgba(69, 190, 208, .65) !important;
  border-radius: 28px !important;
  box-shadow:
    inset 0 2px 5px rgba(255,255,255,.95),
    0 5px 18px rgba(20,120,160,.18) !important;
}

/* glassy buttons */
button,
[role="button"] {
  border-radius: 22px !important;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,.95),
    rgba(157,232,239,.72)
  ) !important;
  border: 1px solid rgba(255,255,255,.95) !important;
  box-shadow:
    inset 0 2px 3px white,
    0 3px 10px rgba(27,130,160,.18) !important;
  color: #17617d !important;
}

/* aquatic links */
a {
  color: #087eaa !important;
}

/* softer rounded imagery */
img {
  border-radius: 12px;
}
